def generate_unique_dialogue() -> dict[str, Any]:
    """Генерация диалога с уникальным текстом — гарантированный промах кэша.

    Хэш диалога считается только по текстам сообщений, поэтому уникальность
    обеспечивается уникальной меткой в тексте, а не dialog_id.
    """
    dialog_id = f"load-{uuid.uuid4()}"
    order_id = random.randint(100_000, 999_999)
    amount = random.randint(500, 50_000)
    code = uuid.uuid4().hex[:6].upper()
    user_tag = f"usr_{uuid.uuid4().hex[:8]}"
    fmt_kwargs = {"order_id": order_id, "amount": amount, "code": code, "user_tag": user_tag}

    template = random.choice(DIALOGUE_TEMPLATES)
    # Уникальная метка в тексте первой реплики гарантирует промах кэша даже для
    # шаблонов без плейсхолдеров.
    text_0 = f"{template[0].format(**fmt_kwargs)} [ref:{uuid.uuid4().hex[:12]}]"
    text_1 = template[1].format(**fmt_kwargs)

    messages: list[dict[str, Any]] = [
        {"participant_index": 0, "text": text_0},
        {"participant_index": 1, "text": text_1},
    ]

    if random.random() < 0.35:
        messages.append({"participant_index": 0, "text": random.choice(_USER_FOLLOW_UPS).format(**fmt_kwargs)})
        if random.random() < 0.5:
            messages.append({"participant_index": 1, "text": random.choice(_BOT_FOLLOW_UPS)})

    return {"dialog_id": dialog_id, "messages": messages}


def make_payload(dialogue: dict[str, Any], *, audit_mode: str = "off") -> dict[str, Any]:
    """Обёртка диалога в тело POST /predict (нагрузка по умолчанию без аудита в ClickHouse)."""
    return {"dialogues": [dialogue], "audit_mode": audit_mode}


def make_cache_payload(
    dialog_id: str = "load-cache-test-001",
    text: str = "Детерминированный диалог для проверки кэша Redis.",
    *,
    audit_mode: str = "off",
) -> dict[str, Any]:
    """Детерминированный диалог (гарантированный хит кэша после первого запроса)."""
    return {
        "dialogues": [
            {
                "dialog_id": dialog_id,
                "messages": [
                    {"participant_index": 0, "text": text},
                    {"participant_index": 1, "text": f"{text} Ответ на реплику."},
                ],
            }
        ],
        "audit_mode": audit_mode,
    }
